const qa = $('Ejecutar Pruebas QA de Rutas').first().json;
const httpResult = $('Health Check Servidor Vite').first()?.json || {};
const servidorOnline = !httpResult.error;

let reporte = `📋 REPORTE DE AUDITORÍA QA - PIZARRAMASTERY\n`;
reporte += `==============================================\n`;
reporte += `Fecha: ${qa.timestamp}\n`;
reporte += `Servidor Frontend (localhost:5173): ${servidorOnline ? 'ONLINE 🟢' : 'OFFLINE 🔴'}\n`;
reporte += `Total de Pruebas: ${qa.totalPruebas}\n`;
reporte += `Pruebas Aprobadas: ${qa.aprobadas}/${qa.totalPruebas} (${qa.tasaExito})\n`;
reporte += `Veredicto Final: ${qa.estadoGeneral}\n`;
reporte += `==============================================\n\n`;

qa.casos.forEach(c => {
  reporte += `[${c.resultado}] ${c.id}: ${c.nombre}\n`;
  reporte += `  - Ruta: ${c.ruta}\n`;
  reporte += `  - Rol: ${c.rol} | Autenticado: ${c.autenticado ? 'SÍ' : 'NO'}\n`;
  reporte += `  - Esperado: ${c.estadoEsperado} -> ${c.vistaEsperada}\n\n`;
});

return [{
  json: {
    veredicto: qa.estadoGeneral,
    servidorFrontend: servidorOnline ? 'Conectado (localhost:5173)' : 'Desconectado',
    resumen: `${qa.aprobadas}/${qa.totalPruebas} pruebas superadas con éxito`,
    fecha: qa.timestamp,
    reporteTexto: reporte,
    detallePruebas: qa.casos
  }
}];
